// Normalize Filter Classify
// Extracts normalized fields from incoming WAHA NOWEB payload
// and enriches with location info loaded from Supabase

const item = $input.first();
const body = item.json.body;
const payload = body?.payload || {};

// Load locations from previous node (passed as context via $('Load Locations').all())
let SNIR_GROUPS = [];
let SNIR_GROUP_MAP = {};
try {
  const locItems = $('Load Locations').all();
  if (locItems && locItems.length > 0) {
    const locations = Array.isArray(locItems[0].json) ? locItems[0].json : locItems.map(i => i.json);
    for (const loc of locations) {
      if (loc.wa_group_jid) {
        SNIR_GROUPS.push(loc.wa_group_jid);
        SNIR_GROUP_MAP[loc.wa_group_jid] = {
          id: loc.id,
          name: loc.name,
          source_group: loc.source_group,
          timezone: loc.timezone,
          manager_wa: loc.manager_wa
        };
      }
    }
  }
} catch (e) {
  // fallback: empty maps for testing
  SNIR_GROUPS = [];
  SNIR_GROUP_MAP = {};
}

const event_type = body?.event || 'unknown';
const session = body?.session || '';

// Extract group JID and sender JID
const group_jid = (payload.from || '').endsWith('@g.us') ? payload.from : null;
const sender_jid = payload.participant
  || payload?._data?.key?.participant
  || payload?.participantAlt
  || (group_jid ? null : payload.from)
  || '';

// Extract message body
const msg_body = payload.body || payload.text || '';

// Extract timestamp
const timestamp_unix = payload.timestamp || Math.floor(Date.now() / 1000);

// Extract message ID (dedupe key)
const wa_message_id = payload.id || '';

// Extract quoted message ID (thread linking)
const quoted_msg_id = payload?.replyTo?.id || payload?.quotedMsgId || null;

// Determine source group from group JID
const loc_info = group_jid ? (SNIR_GROUP_MAP[group_jid] || null) : null;
const source_group = loc_info?.source_group || null;
const location_id = loc_info?.id || null;

// Filter: only process messages from known Snir groups
// (if SNIR_GROUPS is empty we pass all for testing)
if (SNIR_GROUPS.length > 0 && group_jid && !SNIR_GROUPS.includes(group_jid)) {
  return [];
}

// Detect edit/revoke event types
const is_revoked = event_type === 'message.revoked';
const is_edited = event_type === 'message.edited';

// Build normalized object
const _normalized = {
  event_type,
  session,
  group_jid,
  sender_jid,
  body: msg_body,
  timestamp_unix,
  wa_message_id,
  quoted_msg_id,
  source_group,
  location_id,
  is_revoked,
  is_edited,
  tenant_id: $env.TENANT_ID
};

return [{ json: { ...item.json, _normalized } }];

