// Parse Classifier Output
// Parses Anthropic API response and extracts class/confidence/fields

const item = $input.first();
const anthropicResponse = item.json;

let classifierResult = {
  class: 'unknown',
  confidence: 0,
  fields: { reason: 'parse_error' }
};

try {
  // Anthropic API response has content[0].text
  const rawText = anthropicResponse?.content?.[0]?.text || '';

  // Strip any markdown code fences if present
  const jsonText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

  const parsed = JSON.parse(jsonText);
  classifierResult = {
    class: parsed.class || 'unknown',
    confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0,
    fields: parsed.fields || {}
  };
} catch (e) {
  classifierResult = {
    class: 'unknown',
    confidence: 0,
    fields: { reason: 'json_parse_failed: ' + String(e) }
  };
}

// Merge classifier result into item
const normalized = $('Normalize Filter Classify').item.json._normalized;
const rawMsgRow = $('Insert raw_message').item.json;

return [{
  json: {
    ...item.json,
    _normalized: normalized,
    _raw_message_id: Array.isArray(rawMsgRow) ? rawMsgRow[0]?.id : rawMsgRow?.id,
    _classifier: classifierResult
  }
}];

// Extract Single Sale
// Parses sale data from classifier output and resolves employee + thread

const item = $input.first();
const normalized = item.json._normalized;
const fields = item.json._classifier.fields || {};
const rawMsgId = item.json._raw_message_id;

// Parse amount from currency_raw or direct amount field
function parseAmount(raw) {
  if (typeof raw === 'number') return raw;
  if (!raw) return null;
  const s = String(raw).replace(/[\$\u20b1,\s]/g, '').toLowerCase();
  if (s.endsWith('m')) return parseFloat(s) * 1000000;
  if (s.endsWith('k')) return parseFloat(s) * 1000;
  return parseFloat(s) || null;
}

const amount = fields.amount != null ? fields.amount : parseAmount(fields.currency_raw);

// Map sale_state from classifier to valid DB values (exclude 'cancelled')
let sale_state = fields.sale_state || 'open';
if (sale_state === 'cancelled') sale_state = null;

// Determine outcome
let outcome = null;
if (fields.sale_state === 'closed') outcome = 'success';
if (fields.sale_state === 'cancelled') outcome = 'failed';

// occurred_at from timestamp
const occurred_at = normalized.timestamp_unix
  ? new Date(normalized.timestamp_unix * 1000).toISOString()
  : new Date().toISOString();

// sale_thread_id: will be resolved via Supabase lookup in next step
// For now, pass quoted_msg_id for thread lookup
const quoted_msg_id = normalized.quoted_msg_id;

return [{
  json: {
    ...item.json,
    _sale: {
      tenant_id: normalized.tenant_id,
      location_id: normalized.location_id,
      lead_name: fields.lead_name || null,
      helper_names: fields.helper_names || [],
      amount,
      product_hint: fields.product_hint || null,
      payment_hint: fields.payment_hint || null,
      sale_state: sale_state || 'open',
      outcome,
      occurred_at,
      raw_message_id: rawMsgId,
      confidence: item.json._classifier.confidence,
      source_group: normalized.source_group,
      quoted_msg_id,
      sender_jid: normalized.sender_jid,
      currency_raw: fields.currency_raw
    }
  }
}];

// Insert live_event_employees
// Builds junction rows for lead + helpers

const item = $input.first();
const saleData = $('Extract Single Sale').item.json._sale;
const liveEventRow = Array.isArray(item.json) ? item.json[0] : item.json;
const liveEventId = liveEventRow?.id;
const tenantId = saleData.tenant_id;

const rows = [];

// Lead
const leadEmployeeId = $('Resolve Lead Employee').item.json;
if (leadEmployeeId && liveEventId) {
  rows.push({
    tenant_id: tenantId,
    live_event_id: liveEventId,
    employee_id: leadEmployeeId,
    role: 'lead',
    pct_share: null,
    amount_credited: saleData.amount
  });
}

// Helpers — would need resolve_employee calls for each; for now store as-is if we had IDs
// In production, loop through saleData.helper_names and call resolve_employee for each
// For Phase 1, we pass helpers as separate HTTP calls or batch; simplified here:

if (rows.length === 0) {
  return [{ json: { skipped: true, reason: 'no_employee_ids_resolved' } }];
}

return rows.map(r => ({ json: r }));

// Extract EOD Summary fields
// Parses date, location, cash, card, total, payment methods, employee amounts

const item = $input.first();
const normalized = item.json._normalized;
const fields = item.json._classifier.fields || {};
const rawMsgId = item.json._raw_message_id;

// Parse amount helper
function parseAmount(raw) {
  if (typeof raw === 'number') return raw;
  if (!raw) return null;
  const s = String(raw).replace(/[\$\u20b1,\s]/g, '').toLowerCase();
  if (s.endsWith('m')) return parseFloat(s) * 1000000;
  if (s.endsWith('k')) return parseFloat(s) * 1000;
  return parseFloat(s) || null;
}

// Determine sale date from fields.date or timestamp
let sale_date = null;
if (fields.date) {
  // e.g. '4/20' — assume current year, Manila time
  try {
    const parts = fields.date.split('/');
    if (parts.length === 2) {
      const now = new Date();
      sale_date = `${now.getFullYear()}-${String(parts[0]).padStart(2,'0')}-${String(parts[1]).padStart(2,'0')}`;
    }
  } catch (e) {
    sale_date = null;
  }
}
if (!sale_date) {
  // Fall back to timestamp date in Manila time
  const ts = normalized.timestamp_unix ? normalized.timestamp_unix * 1000 : Date.now();
  const d = new Date(ts);
  // Convert to Asia/Manila (UTC+8)
  const manilaOffset = 8 * 60;
  const localDate = new Date(d.getTime() + manilaOffset * 60000);
  sale_date = localDate.toISOString().split('T')[0];
}

const cash = parseAmount(fields.cash);
const card = parseAmount(fields.card);
const total = parseAmount(fields.total);

const payment_methods = (fields.payment_methods || []).map(pm => ({
  method: pm.method,
  amount: parseAmount(pm.amount)
}));

const employee_totals = (fields.employee_totals || []).map(et => ({
  name: et.name,
  amount: parseAmount(et.amount)
}));

return [{
  json: {
    ...item.json,
    _eod: {
      tenant_id: normalized.tenant_id,
      location_id: normalized.location_id,
      sale_date,
      cash,
      card,
      total,
      lead_source: 'jpl_totals',
      raw_message_id: rawMsgId,
      payment_methods,
      employee_totals,
      location_hint: fields.location_hint || null
    }
  }
}];

// Build payment_breakdown rows and employee_sales rows from EOD extract

const item = $input.first();
const eodData = $('Extract EOD').item.json._eod;
const dailyTotalsRow = Array.isArray(item.json) ? item.json[0] : item.json;
const dailyTotalsId = dailyTotalsRow?.id;
const tenantId = eodData.tenant_id;

const rows = [];

if (dailyTotalsId && eodData.payment_methods && eodData.payment_methods.length > 0) {
  for (const pm of eodData.payment_methods) {
    if (pm.amount != null) {
      rows.push({
        tenant_id: tenantId,
        daily_totals_id: dailyTotalsId,
        method: pm.method,
        amount: pm.amount
      });
    }
  }
}

if (rows.length === 0) {
  return [{ json: { skipped: true, reason: 'no_payment_methods' } }];
}

return rows.map(r => ({ json: r }));
